"""Individual utility objects instead of shared generic launcher symbols."""
from classic_application_art import page, book


def draw(b,v):
    r,p,c,line=b.rect,b.poly,b.circle,b.path
    ext=lambda name:b.classic_extensions.symbol(b,name)
    if v=='powershell':return p('12,16 46,4 55,10 21,23',b.LIGHT)+p('12,16 21,23 21,51 12,44',b.DARK)+p('21,23 55,10 55,40 21,53',b.BLUE)+line('M27 29L35 32L27 42M38 40L48 36',stroke=b.LIGHT,w=2.4)
    if v in ('lxterminal','mate-terminal','qterminal','xfce-terminal','xterm','uxterm','yakuake'):
        colour={'lxterminal':b.TEAL,'mate-terminal':b.DARK,'qterminal':b.BLUE,'xfce-terminal':b.PURPLE,'xterm':b.INK,'uxterm':b.INK,'yakuake':b.DARK}[v]
        screen=p('13,19 46,6 56,13 23,26',b.LIGHT)+p('13,19 23,26 23,49 13,42',b.MID)+p('23,26 56,13 56,39 23,52',b.PAPER)+p('27,28 52,18 52,35 27,45',colour)
        if v=='xterm':return screen+line('M31 29L47 36M47 23L31 43',stroke=b.LIGHT,w=2)
        if v=='uxterm':return screen+line('M30 27V36Q30 46 40 39V23',stroke=b.LIGHT,w=2)+p('42,38 57,32 57,49 42,55',b.LIGHT)+line('M46 43V50M50 40V49',stroke=b.PURPLE,w=1.5)
        if v=='mate-terminal':return screen+line('M30 39V27L37 32L43 22V34',stroke=b.TEAL,w=2.5)
        if v=='qterminal':return screen+c(39,30,7,b.LIGHT)+c(39,30,4,b.BLUE)+line('M43 33L50 38',stroke=b.LIGHT,w=3)
        if v=='xfce-terminal':return screen+line('M31 34L37 37L31 42',stroke=b.LIGHT,w=2)+c(44,28,5,b.PAPER)+c(40,22,3,b.PAPER)+c(48,22,3,b.PAPER)+line('M44 30L51 33',w=1)
        if v=='yakuake':return screen+line('M38 14V35M32 28L38 35L44 22',stroke=b.GOLD,w=3)+p('18,9 43,1 54,7 29,16',b.MID)
        return screen+line('M29 33L36 36L29 42M39 38L48 34',stroke=b.LIGHT,w=2)+line('M12 48L21 53L31 50',stroke=b.TEAL,w=3)
    if v=='terminal-settings':return b.group(draw(b,'xfce-terminal'),'translate(-3 -4) scale(.8)')+b.group(b.wrench(),'translate(36 31) scale(.37)')
    if v=='qterminal-drop':return b.group(draw(b,'qterminal'),'translate(-3 -4) scale(.8)')+line('M49 28V50M43 43L49 50L55 43',stroke=b.GOLD,w=3)
    if v=='iso-writer':return b.ellipse(29,28,20,14,b.PAPER)+b.ellipse(29,28,5,3,b.MID)+line('M16 24L27 15M20 29L35 18',stroke=b.BLUE,w=1.5)+p('36,32 54,25 54,47 36,55',b.DARK)+line('M41 39L49 36M41 45L47 42',stroke=b.LIGHT,w=1.5)
    if v=='usb-writer':return p('13,21 24,16 30,20 19,26',b.MID)+p('19,26 30,20 49,39 38,45',b.PURPLE)+p('38,45 49,39 52,43 41,50',b.DARK)+line('M36 12V36M30 29L36 36L42 29',stroke=b.GOLD,w=3)
    if v=='usb-format':return p('15,20 26,14 32,18 21,25',b.MID)+p('21,25 32,18 50,35 39,43',b.TEAL)+p('39,43 50,35 53,40 42,48',b.DARK)+line('M29 34L53 12',stroke=b.GOLD,w=5)+p('44,12 55,10 58,15 51,22',b.PAPER)
    if v in ('gparted','partitionmanager'):
        s=b.drive('harddisk')+b.ellipse(32,27,15,9,b.TEAL)+p('32,27 43,20 47,27',b.RED)+p('32,27 47,27 38,35',b.GOLD)
        if v=='partitionmanager':s+=b.group(b.wrench(),'translate(37 24) scale(.4)')
        else:s+=line('M19 28L41 17M26 32L47 23',stroke=b.LIGHT,w=1)
        return s
    if v=='diskfree':return b.drive('harddisk')+r(8,8,38,10,b.PAPER)+r(10,10,22,6,b.TEAL,'none')+r(34,10,10,6,b.GOLD,'none')
    if v=='kwikdisk':return b.group(b.drive('harddisk'),'translate(-4 12) scale(.72)')+b.group(b.drive('harddisk'),'translate(20 -1) scale(.66)')
    if v=='usermount':return b.drive('harddisk')+line('M35 10V32M29 17L35 10L41 17',stroke=b.GOLD,w=3)
    if v=='gnome-disks':return b.drive('harddisk')+b.ellipse(32,24,16,9,b.LIGHT)+b.ellipse(32,24,5,3,b.DARK)+line('M13 29L35 24',stroke=b.GOLD,w=3)
    if v=='htop':return p('10,15 43,3 55,10 22,24',b.LIGHT)+p('22,24 55,10 55,42 22,56',b.DARK)+''.join(line(f'M27 {29+i*5}L{45-i*3} {22+i*5+i}',stroke=b.TEAL if i%2 else b.GOLD,w=2) for i in range(4))
    if v=='qps':return b.group(b.monitor(),'translate(-3 7) scale(.88)')+line('M17 22L25 18L31 27L36 9L42 19L49 14',stroke=b.TEAL,w=2)
    if v=='ksystemlog':return page(b,b.LIGHT,line('M0 3H26M0 10H26M0 17H26M0 24H18',stroke=b.TEAL,w=2))+b.group(b.mark('search'),'translate(37 35) scale(.8)')
    if v=='crashviewer':return b.group(b.monitor(),'translate(-2 5) scale(.9)')+line('M33 9L28 20L40 24L32 41',stroke=b.RED,w=3)+p('41,29 57,50 27,50',b.GOLD)+line('M42 37V43M42 46V47',w=2)
    if v=='etherape':return ''.join(line(f'M32 28L{x} {y}',stroke=b.TEAL,w=2)+c(x,y,5,b.PURPLE if x<32 else b.BLUE) for x,y in ((13,12),(47,10),(9,40),(54,39),(32,51)))+c(32,28,8,b.GOLD)
    if v=='nmapsi':return c(32,28,21,b.TEAL)+''.join(c(32,28,radius,'none',b.LIGHT,1) for radius in (7,14))+line('M32 28L47 13M11 28H53M32 7V49',stroke=b.LIGHT,w=1.5)+c(21,34,3,b.GOLD)
    if v=='barrier':return b.group(b.monitor(),'translate(-4 13) scale(.62)')+b.group(b.monitor(),'translate(24 -2) scale(.62)')+line('M17 44L38 33M17 44L25 44M38 33L31 33',stroke=b.GOLD,w=3)
    if v=='quicksynergy':return p('12,33 24,17 46,26 34,42',b.BLUE)+p('24,17 27,10 50,19 46,26',b.LIGHT)+line('M13 45L38 12M8 39L13 45L22 44',stroke=b.GOLD,w=3)
    if v=='smb4k':return b.group(b.classic_extensions.symbol(b,'network'),'translate(-4 4) scale(.75)')+b.group(b.folder('remote'),'translate(28 12) scale(.57)')
    if v=='kwallet':return p('11,21 42,10 53,17 22,30',b.GOLD)+p('11,21 22,30 22,52 11,44',b.DARK)+p('22,30 53,17 53,41 22,54',b.GOLD)+p('36,31 55,24 55,36 36,43',b.PAPER)+c(47,33,2,b.DARK)
    if v=='kleopatra':return page(b,b.LIGHT,line('M1 2H26M1 8H26M1 14H16',stroke=b.BLUE,w=1.5))+c(41,37,10,b.GOLD)+p('34,43 37,56 42,49 47,53 49,41',b.RED)+c(41,37,5,b.PURPLE)
    if v=='gpglog':return page(b,b.LIGHT,line('M1 4H26M1 12H26M1 20H20',w=1.5))+b.group(b.classic_extensions.symbol(b,'key'),'translate(31 24) scale(.45)')
    if v=='file-roller':return p('13,15 45,5 54,12 22,24',b.PAPER)+p('22,24 54,12 54,45 22,57',b.TEAL)+line('M30 21V48',stroke=b.GOLD,w=4)+''.join(line(f'M27 {y}H34',w=1.5) for y in (27,33,39,45))
    if v=='engrampa':return p('9,20 36,8 54,17 27,31',b.GOLD)+p('9,20 27,31 27,52 9,43',b.MID)+p('27,31 54,17 54,39 27,52',b.GOLD)+line('M19 16L41 26V46M14 34L46 21',stroke=b.DARK,w=3)
    if v=='xarchiver':return b.group(b.archive(),'translate(-3 3) scale(.84)')+p('35,20 52,12 56,17 39,25',b.GOLD)+line('M38 29L49 42M49 23L38 47',stroke=b.RED,w=3)
    if v=='kalarm':return b.group(b.clock(),'translate(-2 8) scale(.76)')+b.group(b.classic_extensions.symbol(b,'bell'),'translate(25 -3) scale(.55)')
    if v=='ktimer':return p('16,10 39,2 52,9 28,20',b.LIGHT)+p('16,43 39,34 52,43 28,54',b.GOLD)+line('M21 15L26 28L21 44M46 12L36 26L45 40',stroke=b.PURPLE,w=2.5)+p('25,20 41,14 35,27',b.GOLD)+p('27,38 35,28 41,33',b.GOLD)
    if v=='kteatime':return b.ellipse(30,17,17,7,b.LIGHT)+line('M13 17V39Q15 49 30 49Q46 49 47 39V17',b.PAPER,w=1.5)+b.ellipse(30,17,13,4,b.GOLD)+line('M47 22Q64 16 57 35Q54 39 47 38M23 10Q14 5 23 0M35 10Q28 6 35 2',w=1.5)
    if v=='kcharselect':return book(b,b.BLUE,line('M2 22L10 2L18 22M6 14H14M22 3H27V22',stroke=b.LIGHT,w=2))
    if v=='gucharmap':return p('9,23 38,11 55,22 26,36',b.LIGHT)+''.join(p(f'{14+i*10},{25-i*4+j*8} {22+i*10},{22-i*4+j*8} {25+i*10},{27-i*4+j*8} {17+i*10},{30-i*4+j*8}',b.PURPLE if i==j else b.PAPER) for i in range(3) for j in range(2))
    if v=='fontviewer':return page(b,b.LIGHT,line('M1 22L10 1L20 22M6 14H15M23 2V22M22 12H29',stroke=b.PURPLE,w=2))
    if v=='galculator':return p('13,11 37,2 49,9 25,20',b.LIGHT)+p('25,20 49,9 49,43 25,54',b.DARK)+p('28,22 46,15 46,25 28,32',b.TEAL)+''.join(p(f'{29+i*6},{35-i*2+j*6} {33+i*6},{33-i*2+j*6} {33+i*6},{37-i*2+j*6} {29+i*6},{39-i*2+j*6}',b.GOLD if i==2 else b.PAPER) for i in range(3) for j in range(2))
    if v=='mate-calculator':return b.group(b.calculator(),'translate(-2 4) scale(.8)')+line('M35 12H55M45 4V20M37 29L52 44M52 29L37 44',stroke=b.TEAL,w=3)
    if v=='mouse-tool':return b.group(ext('mouse'),'translate(-5 4) scale(.82)')+b.group(b.mark('check'),'translate(38 36)')
    if v=='kmouth':return p('10,16 45,3 45,29 23,39 15,51 15,42 10,44',b.PAPER)+line('M19 23L36 17M19 30L31 26',stroke=b.BLUE,w=2)+b.group(b.speaker(),'translate(27 26) scale(.48)')
    if v=='emojier':return c(31,25,19,b.GOLD)+c(24,21,2.5,b.INK)+c(38,21,2.5,b.INK)+line('M21 31Q31 43 41 31',w=2)+c(50,41,8,b.PAPER)+c(47,39,1.5,b.INK)+c(53,39,1.5,b.INK)+line('M47 44H53',w=1)
    if v=='sweeper':return line('M23 47L48 7',stroke=b.GOLD,w=4)+p('13,38 30,48 22,57 4,47',b.MID)+line('M8 43L22 52M13 42L26 50',stroke=b.DARK,w=1)+c(41,43,3,b.PURPLE)+c(48,49,2,b.BLUE)
    if v=='kvantum':return p('12,15 35,4 52,13 29,25',b.PAPER)+p('12,15 29,25 29,48 12,39',b.PURPLE)+p('29,25 52,13 52,37 29,50',b.MID)+line('M20 16L20 34M20 25L31 14M20 25L31 35',stroke=b.LIGHT,w=2.5)
    if v=='galternatives':return p('13,19 40,8 51,15 24,28',b.LIGHT)+p('24,28 51,15 51,40 24,53',b.MID)+line('M30 34L36 30L46 39M32 45L46 27',stroke=b.TEAL,w=3)+c(33,21,3,b.PURPLE)
    if v=='winetricks':return line('M18 8H46L42 26Q37 38 31 32Q19 31 18 8Z',b.PAPER,w=1.3)+p('22,18 44,18 40,28 31,33 25,28',b.RED)+line('M31 34V49M21 52H43',w=2)+b.group(b.wrench(),'translate(38 31) scale(.35)')
    if v=='vmware-player':return p('12,15 38,4 52,13 27,25 27,47 12,38',b.GOLD)+p('27,25 52,13 52,37 27,48',b.GOLD)+p('33,27 46,31 33,42',b.LIGHT)
    if v=='vmware-workstation':return p('7,18 29,8 42,17 20,28 20,46 7,37',b.BLUE)+p('25,27 46,17 58,25 37,36 37,53 25,45',b.GOLD)+line('M20 28L42 17V36M37 36L58 25V43',stroke=b.LIGHT,w=2)
    if v=='virt-manager':return b.group(b.monitor(),'translate(-5 6) scale(.78)')+b.group(b.box(),'translate(28 19) scale(.46)')
    if v=='openbox':return p('8,24 32,10 54,20 31,36',b.PAPER)+p('8,24 31,36 31,53 8,42',b.MID)+p('31,36 54,20 54,40 31,53',b.DARK)+p('8,24 3,10 27,0 32,10',b.LIGHT)+p('32,10 44,2 61,12 54,20',b.LIGHT)
    if v=='q4wine':return b.group(draw(b,'winetricks'),'translate(-3 -3) scale(.82)')+c(46,40,10,b.BLUE)+c(46,40,6,b.LIGHT)+line('M51 45L58 52',stroke=b.BLUE,w=3)
    if v=='obconf':return b.group(draw(b,'openbox'),'translate(-3 -4) scale(.84)')+b.group(b.wrench(),'translate(38 33) scale(.35)')
    if v=='wPrefs':return p('10,17 39,5 54,14 24,29',b.LIGHT)+p('24,29 54,14 54,39 24,54',b.PAPER)+p('28,33 36,29 36,47 28,51',b.PURPLE)+p('40,28 50,22 50,40 40,45',b.TEAL)
    if v=='xscreensaver':return b.group(b.monitor(),'translate(-2 7) scale(.85)')+''.join(c(x,y,radius,b.GOLD) for x,y,radius in ((25,16,2),(38,25,3),(44,11,1.5),(31,33,2)))
    if v=='thunar':return b.folder('')+line('M37 15V42M37 17L29 23M37 30L46 26',stroke=b.GOLD,w=4)+c(37,13,5,b.GOLD)
    if v=='thunar-rename':return b.group(draw(b,'thunar'),'translate(-3 3) scale(.78)')+p('38,28 58,20 58,39 38,47',b.PAPER)+line('M42 34L51 30M42 40L53 35',stroke=b.PURPLE,w=2)
    if v=='pcmanfm':return b.folder('')+b.group(b.classic_extensions.symbol(b,'network'),'translate(30 24) scale(.4)')
    if v=='pcmanfm-qt':return b.folder('')+c(44,34,9,b.TEAL)+c(44,34,5,b.LIGHT)+line('M49 39L57 46',stroke=b.TEAL,w=3)
    if v=='xfe':return p('9,15 35,5 46,12 20,23',b.LIGHT)+p('20,23 46,12 46,35 20,47',b.PAPER)+p('31,33 53,23 59,40 37,52',b.MID)+line('M37 37L51 31M40 44L54 38',stroke=b.BLUE,w=2)
    if v=='kmenuedit':return page(b,b.LIGHT,r(1,0,8,8,b.PURPLE)+r(1,12,8,8,b.TEAL)+r(1,24,8,8,b.GOLD)+line('M12 4H28M12 16H28M12 28H28',w=1.5))
    if v=='clipboard':return b.group(b.action('paste'),'translate(2 3) scale(.84)')+c(47,16,7,b.PURPLE)+line('M42 16L46 20L52 11',stroke=b.LIGHT,w=2)
    if v=='shutter':return p('10,14 44,3 52,9 18,22',b.LIGHT)+p('18,22 52,9 52,42 18,56',b.MID)+''.join(line(f'M23 {y}L47 {y-9}',stroke=b.PURPLE,w=3) for y in (25,33,41,49))
    if v=='screengrab':return b.group(b.monitor(),'translate(-3 6) scale(.84)')+b.group(b.camera() if hasattr(b,'camera') else b.app('camera'),'translate(30 27) scale(.45)')
    if v=='kmag':return b.group(b.monitor(),'translate(-5 3) scale(.75)')+b.group(b.mark('search'),'translate(32 31) scale(1.2)')
    if v=='kfind':return b.folder('search')+b.group(b.mark('search'),'translate(35 33) scale(.9)')
    if v=='android-studio':return c(32,24,18,b.TEAL)+line('M32 6L17 48M32 6L48 47M23 29H42',stroke=b.MID,w=5)+c(32,6,4,b.GOLD)+line('M25 18H40',stroke=b.LIGHT,w=1.5)
    if v=='tesourarias':return book(b,b.TEAL,line('M1 8H24M1 16H24M1 24H24M11 2V29',stroke=b.LIGHT,w=1.5))+''.join(b.ellipse(x,y,8,4,b.GOLD) for x,y in ((44,43),(44,39),(49,47)))
    if v=='scientific-agenda':return b.group(b.app('calendar'),'translate(-3 6) scale(.8)')+b.group(b.classic_extensions.symbol(b,'science'),'translate(32 -2) scale(.4)')
    raise ValueError('Unknown utility object: '+v)
